def solve(intervals):
    # Expand each interval by 0 on both sides (no change)
    expanded_intervals = [(start, end) for start, end in intervals]

    # Sort intervals by start
    expanded_intervals.sort(key=lambda x: x[0])

    merged = []
    for interval in expanded_intervals:
        if not merged:
            merged.append(interval)
        else:
            last_start, last_end = merged[-1]
            current_start, current_end = interval
            # Merge if overlapping or touching
            if current_start <= last_end:
                merged[-1] = (last_start, max(last_end, current_end))
            else:
                merged.append(interval)
    return merged
```

